CREATE TABLE `statements` (
  `id` int NOT NULL AUTO_INCREMENT,
  `userId` int NOT NULL,
  `bankAccountId` int NOT NULL,
  `fileName` varchar(256) COLLATE utf8mb4_unicode_ci NOT NULL,
